int input_valid = 1;
if (ig_input.residual == NULL || ig_input.variance == NULL) {
    input_valid = 0;
} else if (!adcs_is_finite_vec3(ig_input.residual) || !adcs_is_finite_vec3(ig_input.variance)) {
    input_valid = 0;
} else {
    for (int i = 0; i < 3; ++i) {
        if (ig_input.variance->m[i] <= FLT64_ZERO) {
            input_valid = 0;
            break;
        }
    }
}

if (ig_config.accept_threshold >= ig_config.reject_threshold) {
    input_valid = 0;
}
if (ig_config.max_consecutive_reject < 1 || ig_config.max_consecutive_reject > 20) {
    input_valid = 0;
}

adcs_vec3_t whitened = {{0, 0, 0}};
double nis_val = 0.0;

if (!input_valid) {
    ig_output.mode = IG_FAULT;
    ig_output.nis = INFINITY;
    ig_output.whitened_norm = INFINITY;
    ig_output.use_measurement = 0;
    return;
