    if (!isfinite(ig_input.variance->x) || !isfinite(ig_input.variance->y) || !isfinite(ig_input.variance->z)) {
        valid_inputs = FALSE32;
    }
    // Check Strictly Positive Variance
    if (ig_input.variance->x <= 0.0 || ig_input.variance->y <= 0.0 || ig_input.variance->z <= 0.0) {
        valid_inputs = FALSE32;
    }
}

// Check Config Constraints
if (valid_inputs && (ig_config.accept_threshold >= ig_config.reject_threshold)) {
    valid_inputs = FALSE32;
}
if (valid_inputs && (ig_config.max_consecutive_reject < 1 || ig_config.max_consecutive_reject > 20)) {
    valid_inputs = FALSE32;
}

