    double v = (i == 0) ? ig_input.variance->x : ((i == 1) ? ig_input.variance->y : ig_input.variance->z);
    double r = (i == 0) ? ig_input.residual->x : ((i == 1) ? ig_input.residual->y : ig_input.residual->z);

    double sqrt_v = sqrt(v);
    if (!isfinite(sqrt_v)) {
        compute_ok = FALSE32;
    }
    whitened[i] = r / sqrt_v;
    if (!isfinite(whitened[i])) {
        compute_ok = FALSE32;
    }
