    ig_output.mode = IG_FAULT;
    ig_output.consecutive_reject = ig_state.consecutive_reject;
    ig_output.nis = INFINITY;
    ig_output.whitened_norm = INFINITY;
    ig_output.use_measurement = 0;
    return;
}

// 5. Decision Logic
unint32 next_count = ig_state.consecutive_reject;
ig_mode_t next_mode = ig_state.mode;

if (nis <= ig_config.accept_threshold) {
    next_mode = IG_ACCEPT;
    next_count = 0;
} else if (nis >= ig_config.reject_threshold) {
    next_mode = IG_REJECT;
    if (next_count < ig_config.max_consecutive_reject) {
        next_count++;
    }
} else {
    // Preserve prior
    if (next_mode == IG_REJECT) {
        if (next_count < ig_config.max_consecutive_reject) {
            next_count++;
        }
    }
}

// Check for Fault Transition
if (next_count >= ig_config.max_consecutive_reject) {
    next_mode = IG_FAULT;
}

// 6. Update State
ig_state.mode = next_mode;
ig_state.consecutive_reject = next_count;

// 7. Assign Outputs
ig_output.mode = next_mode;
ig_output.consecutive_reject = next_count;
ig_output.nis = nis;
ig_output.whitened_norm = wn;
ig_output.use_measurement = (next_mode == IG_ACCEPT) ? 1 : 0;

